function search(placeholder='Search peptides…'){return `<div class="search">${icon('search')}<input type="search" placeholder="${placeholder}" aria-label="${placeholder}" data-search></div>`}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th><span class="table-heading">${helpLabel(h)}</span></th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">No records for this view.</div></td></tr>`}</tbody></table></div>`}
function row(cells,attrs=''){return `<tr ${attrs}>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`}
function footer(count,label='records'){return `<div class="table-footer"><span>${count} ${label}</span><div class="flex">${btn('Previous','chevron-left','data-demo="Pagination"','ghost small')}${btn('1','','data-demo="Page 1"','small')}${btn('Next','chevron-right','data-demo="Pagination"','ghost small')}</div></div>`}
function keyRows(items){return `<div class="key-rows">${items.map(x=>`<div class="key-row"><span>${helpLabel(x[0])}</span><strong class="${x[2]||''}">${x[1]}</strong></div>`).join('')}</div>`}
function field(label,value='',type='text',extra=''){const id='f-'+label.toLowerCase().replace(/[^a-z0-9]/g,'-');return `<div class="field ${extra}"><label for="${id}">${helpLabel(label)}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}></div>`}
function selectField(label,options,extra=''){const id='f-'+label.toLowerCase().replace(/[^a-z0-9]/g,'-');return `<div class="field ${extra}"><label for="${id}">${helpLabel(label)}</label><select id="${id}">${options.map(o=>`<option>${o}</option>`).join('')}</select></div>`}
function notes(label='Notes',placeholder='Add a note…'){return `<div class="field full note-field"><label>${label}<textarea placeholder="${placeholder}"></textarea></label></div>`}
function themeSwitch(labeled=false){return `<div class="theme-switch" aria-label="Appearance">${[['light','sun','Light'],['dark','moon','Dark']].map(([t,i,l])=>`<button data-theme="${t}" class="${state.theme===t?'active':''}" aria-label="${l} theme" aria-pressed="${state.theme===t}" title="${l}">${icon(i)}${labeled?`<span>${l}</span>`:''}</button>`).join('')}</div>`}
function shell(){const nav=state.role==='admin'?navAdmin:workflowNav(); const title=state.role==='agent'&&state.page==='agent'?'Record sale':state.role==='agent'&&state.page==='stock'?'My stock':state.role==='agent'&&state.page==='sales'?'Orders':titles[state.page]||'Dashboard';return `<aside class="sidebar" id="workspace-navigation"><button class="sidebar-toggle" data-action="collapse" aria-controls="workspace-navigation" aria-expanded="${!state.collapsed}" aria-label="${state.collapsed?'Expand navigation':'Collapse navigation'}" title="${state.collapsed?'Expand navigation':'Collapse navigation'}">${icon('chevron-left')}</button><div class="brand"><div class="brand-mark">${icon('dna')}</div><div class="brand-copy">PeptiStock</div></div><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([p,i,l],n)=>`${p==='purchases'?'<div class="nav-label">FINANCE</div>':''}${p==='audit'?'<div class="nav-label">WORKSPACE TOOLS</div>':''}<button class="nav-item ${(state.page===p||(state.page==='peptide'&&p==='catalogue')||(state.page==='request'&&p==='requests')||(state.role==='admin'&&state.page==='agent'&&p==='agents'))?'active':''}" data-page="${p}" aria-label="${l}" ${(state.page===p||(state.page==='peptide'&&p==='catalogue')||(state.page==='request'&&p==='requests')||(state.role==='admin'&&state.page==='agent'&&p==='agents'))?'aria-current="page"':''} title="${l}">${icon(i)}<span>${l}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="user-block"><button class="sidebar-profile" data-page="settings" aria-label="Account settings for ${esc(state.role==='admin'?'Admin O':accountPerson().name)}" title="${esc(state.role==='admin'?'Admin O':accountPerson().name)}">${state.role==='admin'?'<span class="avatar">AO</span>':avatar(accountPerson())}<span class="user-copy">${esc(state.role==='admin'?'Admin O':accountPerson().name)}</span></button><button class="link-btn sidebar-signout" data-page="login" aria-label="View login screen" title="Sign out">${icon('log-out')}</button></div></div></aside><div class="mobile-scrim" data-action="menu" aria-label="Close navigation" role="button" tabindex="-1"></div><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-controls="workspace-navigation" aria-expanded="false">${icon('menu')}</button>${state.page==='dashboard'?'':`<div class="breadcrumb"><strong>${esc(title)}</strong></div>`}<div class="mobile-page-title">${esc(state.page==='dashboard'?'Overview':nav.find(([page])=>page===state.page)?.[2]||title)}</div><div class="top-actions">${themeSwitch()}<button class="icon-btn top-message-button" data-page="messages" aria-label="Messages">${icon('mail')}<span class="chat-top-unread" data-chat-unread ${!messageTotalUnread()?'hidden':''}>${messageTotalUnread()>99?'99+':messageTotalUnread()}</span></button><button class="icon-btn" data-modal="notifications" aria-label="Notifications">${icon('bell')}${notificationUnread()?'<span class="dot" aria-label="Unread notifications"></span>':''}</button></div></header>${workflowSupportBanner()}<div class="content" id="view"></div></main>`}
function barChart(){const vals=[45,68,59,90,120,103,84,95,128,63,77,98,116,107,147,88,76,106,90,120,132,94,151,125];return `<svg class="chart" viewBox="0 0 640 210" role="img" aria-label="Illustrative daily sales split between landed cost and gross profit, October 2026"><g stroke="var(--chart-grid)" stroke-dasharray="3 5">${[20,65,110,155].map(y=>`<line x1="40" x2="635" y1="${y}" y2="${y}"/>`).join('')}</g>${['€1,500','€1,000','€500','€0'].map((v,i)=>`<text x="0" y="${25+i*45}">${v}</text>`).join('')}${vals.map((h,i)=>{let x=49+i*24;return `<g><title>Day ${i+1}: illustrative sales trend</title><rect x="${x}" y="${170-h}" width="10" height="${h*.62}" rx="2" fill="#5b91fa"/><rect x="${x}" y="${170-h*.38}" width="10" height="${h*.38}" rx="1" fill="#44cda6"/></g>`}).join('')}${['1 Oct','6 Oct','12 Oct','18 Oct','24 Oct'].map((v,i)=>`<text x="${48+i*139}" y="199">${v}</text>`).join('')}</svg>`}
function ringAmount(value){const exact=euro(value,Number.isInteger(value)?0:2),compact=Math.abs(value)>=1000000,label=compact?new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',notation:'compact',maximumFractionDigits:2}).format(value):exact;return `<strong class="ring-amount" style="--ring-characters:${label.length}" title="${esc(exact)}" aria-label="${esc(exact)}">${esc(label)}</strong>`}
function donut(cycle){const c=2*Math.PI*78,arc=cycle.total?c*cycle.sold/cycle.total:0;return `<div class="donut"><svg viewBox="0 0 200 200" role="img" aria-label="${transferMoney(cycle.remaining)} in agent stock and ${transferMoney(cycle.sold)} in sales awaiting settlement"><circle cx="100" cy="100" r="78" stroke="var(--line)"/>${cycle.total?`<circle cx="100" cy="100" r="78" stroke="var(--blue)"/><circle cx="100" cy="100" r="78" stroke="var(--purple)" stroke-dasharray="${arc} ${c}"/>`:''}</svg><div class="donut-text">${ringAmount(cycle.total/100)}<small>Active value</small></div></div>`}
function agentsTable(){
 const data=agents.map((a,i)=>({a,i,type:accountTypes[flowProfile(i)].label,units:progressTotals(i).units,sales:euro(progressTotals(i).allSales),due:flowProfile(i)==='wholesale'?'Prepaid':transferMoney(transferSnapshot(i).net+transferSnapshot(i).pending)}));
 return `<div class="agent-overview-desktop">${table(['Agent','Agreement','Stock','Sales','To business','Action'],data.map(({a,i,type,units,sales,due})=>row([avatar(a)+' '+a.name,badge(type,'blue'),units+' vials',sales,due,btn('View','arrow-up-right',`data-agent="${i}"`,'small')])) )}</div><div class="agent-overview-mobile">${data.map(({a,i,type,units,sales,due})=>`<button class="agent-overview-card" data-agent="${i}" aria-label="View ${esc(a.name)} overview"><span class="agent-overview-identity">${avatar(a)}<span class="agent-overview-name"><strong>${esc(a.name)}</strong><small>${esc(type)}</small></span>${icon('chevron-right')}</span><span class="agent-overview-figures"><span><small>Stock</small><strong>${units} <span class="agent-overview-unit">vials</span></strong></span><span><small>Sales</small><strong>${sales}</strong></span><span><small>To business</small><strong>${due}</strong></span></span></button>`).join('')}</div>`
}
function dashboard(){return `<h1 class="sr-only">Dashboard</h1>${trendPanel()}<div class="bottom-grid"><section class="panel agent-overview-panel">${panelHead('Agents overview','',`<button class="link-btn" data-page="agents">All agents ${icon('arrow-right')}</button>`)}${agentsTable()}<div class="table-footer"><span>${euro(financeAccountIndices().reduce((n,i)=>n+progressCash(i),0))} owed by agents · includes pending</span><button class="link-btn" data-page="payments">Review transfers ${icon('arrow-right')}</button></div></section><section class="panel">${panelHead('Stock to watch','',badge('Low stock','orange'))}<div class="panel-body low-stock-list">${orderLowStockItems()}</div></section></div><div class="metrics mt">${metric('Stock requests',requestRecords().filter(r=>r.status==='requested').length,'send','orange','')}${metric('Deliveries in progress',requestRecords().filter(r=>r.status==='dispatched').length,'truck','blue','')}${metric('Transfers confirmed',transferMoney(transferBusinessTotals().confirmed),'circle-check','green','')}${metric('Transfers awaiting confirmation',transferMoney(transferBusinessTotals().pending),'wallet','orange','')}</div>`}
function agentList(){return pageHead('Your partners','A shared business. A workspace of their own.',btn('Invite agent','user-plus','data-modal="invite"','primary'))+`<div class="panel mb"><div class="toolbar">${search('Search agents…')}<div class="tabs"><button class="active" data-listfilter="all">All agents <span class="muted">4</span></button><button data-listfilter="Three-way">Three-way</button><button data-listfilter="20% commission">Commission</button></div></div></div><div class="agent-cards">${agents.map((a,i)=>`<article class="panel agent-card" data-searchable="${a.name.toLowerCase()}" data-model="${a.model}"><div class="flex">${avatar(a)}<div class="grow"><h3>${a.name}</h3><small>${a.model==='Three-way'?'Three-way investment':'20% profit commission'}</small></div>${badge('Active','green')}</div><div class="agent-stats"><div><small>Stock</small><strong>${a.stock} <small>vials</small></strong></div><div><small>Recorded sales</small><strong>${euro(a.sales)}</strong></div><div><small>Cash held</small><strong class="green">${euro(a.cash)}</strong></div></div><div class="flex between"><small>Remaining stock value</small><strong>${euro(a.value)}</strong></div><div class="agent-card-bottom mt"><button class="link-btn" data-modal="manage-agent" data-agent-index="${i}">Manage access</button>${btn('Open workspace','arrow-up-right',`data-agent="${i}"`,'small')}</div></article>`).join('')}<article class="panel agent-card" style="border-style:dashed;display:grid;place-content:center;text-align:center;min-height:225px"><span class="metric-icon" style="margin:0 auto 12px">${icon('user-plus')}</span><h3>Make room for growth</h3><p class="muted" style="font-size:13px;margin:8px 0 17px">Invite your next partner.</p>${btn('Invite agent','plus','data-modal="invite"','small')}</article></div>`}
function stockTable(list,agentOnly=false){let isAgent=state.role==='agent'||agentOnly;return `<div class="table-wrap"><table class="stock-table"><thead><tr><th>Peptide</th><th>${isAgent?'Stock':'Remaining'}</th><th class="hide-mobile">Batch</th>${!isAgent?'<th class="hide-mobile">Assigned</th><th class="hide-mobile">Sold</th><th class="hide-mobile">Landed cost</th>':''}<th>Price</th><th>${isAgent?'Discount':'Value'}</th><th></th></tr></thead><tbody>${list.map(p=>`<tr data-searchable="${p.name.toLowerCase()} ${p.dose.toLowerCase()}" data-quantity="${p.qty}" data-low-threshold="${p.lowStockThreshold??5}"><td><div class="agent-cell">${productGlyph(p)}<div class="product-name"><strong>${esc(p.name)}</strong> <small>${doseMarkup(p.dose)}</small></div></div></td><td><span class="stock-pill ${p.qty===0?'zero':stockIsLow(p)?'low':''}">${p.qty}</span></td><td class="hide-mobile muted">${p.batch}</td>${!isAgent?`<td class="hide-mobile">${p.qty+2}</td><td class="hide-mobile">2</td><td class="hide-mobile">${euro(p.cost,2)}</td>`:''}<td class="num">${euro(p.price)}</td><td>${isAgent?`<input class="inline-input" type="number" min="0" max="10" value="0" aria-label="Discount percent for ${esc(p.name)} ${esc(p.dose)}" title="Discount in percent, up to 10%" data-discount="${p.id}">`:`<span class="num">${euro(p.price*p.qty)}</span>`}</td><td>${btn('Sell','',`data-sell="${p.id}" ${p.qty===0?'disabled':''}`,'primary small')}</td></tr>`).join('')}</tbody></table></div>`}
function stock(){return state.role==='agent'?workflowStock():requestStockOverview()}
function catalogue(){const listed=products.filter(p=>!!p.catalogueArchived===(catalogueStatus==='archived'));return pageHead('Peptide catalogue','',btn('Add peptide','plus','data-modal="product"','primary'))+`<section class="panel catalogue-panel"><div class="toolbar">${search()}<select id="catalogue-category" aria-label="Filter by category"><option value="all">All categories</option>${productCategories.map(c=>`<option value="${c.id}" ${catalogueCategory===c.id?'selected':''}>${c.label}</option>`).join('')}</select><select id="catalogue-status" aria-label="Catalogue visibility"><option value="active" ${catalogueStatus==='active'?'selected':''}>Active products</option><option value="archived" ${catalogueStatus==='archived'?'selected':''}>Archived products</option></select>${btn('Import price list','upload','data-modal="import"','small')}</div>${table(['Peptide / strength','Category','Landed cost','Default selling price',''],listed.map(p=>row([`<button class="catalogue-product-link" data-catalogue-open="${p.id}" aria-label="Open ${esc(p.name)} ${esc(p.dose)}">${productGlyph(p)}${productLabel(p)}</button>`,badge(categoryFor(p).label),`<strong>${euro(p.cost,2)}</strong>`,`<strong>${euro(p.price,2)}</strong>`,`<span class="catalogue-row-arrow" aria-hidden="true">${icon('chevron-right')}</span>`],`data-catalogue-row="${p.id}" data-searchable="${esc((p.name+' '+p.dose).toLowerCase())}" data-category="${categoryFor(p).id}" ${catalogueCategory!=='all'&&categoryFor(p).id!==catalogueCategory?'hidden':''}`)))}<div class="table-footer"><span>${listed.length} products</span></div></section>`}
function catalogueSelected(){const id=new URLSearchParams(location.search).get('product');return id!==null?products.find(p=>String(p.id)===id):null}
function catalogueOpen(id){if(state.role!=='admin')return;const p=products.find(p=>p.id===Number(id));if(!p)return;const url=new URL(location.href);url.searchParams.set('product',p.id);history.replaceState(null,'',url);go('peptide')}
function catalogueDetail(){const p=catalogueSelected();if(!p)return `<section class="panel"><div class="panel-body"><h2>Product not found</h2>${btn('Back to catalogue','arrow-left','data-page="catalogue"','mt')}</div></section>`;const r=protocolRecords().get(p.id),d=r?.current;return `<div class="order-detail-toolbar">${btn('Catalogue','arrow-left','data-page="catalogue"','small')}<button class="icon-btn" data-catalogue-actions="${p.id}" aria-label="Product actions">${icon('ellipsis')}</button></div><div class="catalogue-detail-grid"><section class="panel catalogue-detail-main"><div class="panel-body"><div class="catalogue-detail-identity">${productGlyph(p)}<div class="grow"><h1>${esc(p.name)}</h1><span class="product-dose">${esc(p.dose)}</span></div>${p.catalogueArchived?badge('Archived','orange'):''}</div><div class="catalogue-detail-category">${badge(categoryFor(p).label)}</div><div class="catalogue-prices"><div><span>Landed cost ${info('Landed cost')}</span><strong>${euro(p.cost,2)}</strong></div><div><span>Default selling price ${info('Default selling price')}</span><strong>${euro(p.price,2)}</strong></div></div><div class="key-row"><span>Low-stock threshold ${info('Low stock')}</span><strong>${p.lowStockThreshold??5} units</strong></div><div class="form-actions">${btn('Edit details','pencil',`data-product="${p.id}"`,'primary')}</div></div></section><section class="panel catalogue-detail-protocol"><div class="panel-head"><h2>Protocol</h2></div><div class="panel-body"><div class="catalogue-pdf">${icon('file-text')}<div class="grow"><strong>${d?esc(d.name):'No protocol uploaded'}</strong>${d?`<small>PDF · v${r.revision} · ${esc(d.date)}</small><small>${esc(d.batch)}</small>`:''}</div></div><div class="catalogue-protocol-actions">${d?btn('View PDF','eye',`data-protocol-view="${p.id}"`,'small'):''}${btn(d?'Replace PDF':'Upload PDF',d?'refresh-cw':'upload',d?`data-protocol-replace="${p.id}"`:`data-protocol-upload="${p.id}"`,'primary small')}</div></div></section></div>`}
function catalogueActions(id){if(state.role!=='admin'||workflow.support)return;const p=products[id];if(!p)return;openModal('Product actions',`<div class="catalogue-action-list">${btn('Edit details','pencil',`data-product="${id}"`)}${btn('Upload protocol','upload',`data-protocol-upload="${id}"`)}${btn(p.catalogueArchived?'Restore to catalogue':'Remove from catalogue',p.catalogueArchived?'archive-restore':'archive',`data-catalogue-archive="${id}"`)}</div>`)}
function catalogueArchivePrompt(id){if(state.role!=='admin'||workflow.support)return;const p=products[id];if(!p)return;openModal(p.catalogueArchived?'Restore product?':'Remove from catalogue?',`<p>${esc(p.name)} · ${esc(p.dose)}</p><p class="muted mt">${p.catalogueArchived?'Show this product in the active catalogue again.':'Moves this product to Archived products. Existing stock, orders, prices and protocols are kept. This does not recall stock or stop existing fulfilment.'}</p><div class="form-actions">${btn('Cancel','','data-close')}${btn(p.catalogueArchived?'Restore product':'Archive product','check',`data-catalogue-confirm-archive="${id}"`,'primary')}</div>`)}
function catalogueArchive(id){if(state.role!=='admin'||workflow.support)return false;const p=products[id];if(!p)return false;p.catalogueArchived=!p.catalogueArchived;priceEvent((p.catalogueArchived?'Archived catalogue entry · ':'Restored catalogue entry · ')+p.name+' '+p.dose);closeModal();render();toast(p.catalogueArchived?'Moved to archived products':'Restored to catalogue');return true}
document.addEventListener('click',e=>{const open=e.target.closest('[data-catalogue-open]');if(open){catalogueOpen(open.dataset.catalogueOpen);return}const row=e.target.closest('[data-catalogue-row]');if(row&&!e.target.closest('button,a,input,select')){catalogueOpen(row.dataset.catalogueRow);return}const action=e.target.closest('[data-catalogue-actions]');if(action)catalogueActions(Number(action.dataset.catalogueActions));const archive=e.target.closest('[data-catalogue-archive]');if(archive)catalogueArchivePrompt(Number(archive.dataset.catalogueArchive));const confirm=e.target.closest('[data-catalogue-confirm-archive]');if(confirm)catalogueArchive(Number(confirm.dataset.catalogueConfirmArchive))});
document.addEventListener('change',e=>{if(e.target.id==='catalogue-status'){catalogueStatus=e.target.value;state.search='';render()}});

function purchases(){return pageHead('Purchase orders','Every shipment. Its own costs. A clear trail.',btn('New shipment','plus','data-modal="shipment"','primary'))+`<div class="metrics">${metric('Stock purchases','€19,880','package-plus','','Across all batches')}${metric('Shared costs','€1,480','truck','orange','Included in stock purchases')}${metric('Open purchase orders','2','clock-3','blue','One draft · one in transit')}${metric('Average landed cost','€40.00','calculator','green','Per remaining vial')}</div><section class="panel">${panelHead('Shipments','Exchange rates and costs are fixed per batch.',info('Landed cost'))}${table(['Order','Date','Supplier','Items / vials','Original value','Exchange rate','Landed total','Status',''],[row(['PO-026','19 Oct 2026','Decode Peptides','3 / 40','$1,000.00','USD → EUR 0.86','€1,168.20',badge('Received','green'),btn('View costs','arrow-up-right','data-modal="shipment"','small')]),row(['PO-027','24 Oct 2026','Decode Peptides','6 / 80','$2,400.00','USD → EUR 0.86','€2,354.00',badge('In transit','blue'),btn('View costs','arrow-up-right','data-modal="shipment"','small')]),row(['PO-028','26 Oct 2026','Decode Peptides','4 / 60','$1,800.00','Not fixed','—',badge('Draft','orange'),btn('Edit draft','pencil','data-modal="shipment"','small')])])}</section><div class="split equal mt"><section class="panel">${panelHead('How costs are allocated','Choose one method for each shared expense.')}<div class="panel-body">${keyRows([['By quantity','Cost per vial'],['By purchase value','Proportional to item value'],['Manual','Set an amount per product']])}<div class="banner mt">${icon('history')}<span>Cost corrections create a new revision. Prior sales keep their recorded costs.</span></div></div></section><section class="panel">${panelHead('Recent cost corrections','An audit trail, not an overwritten number.')}<div class="timeline"><div class="timeline-item"><span class="timeline-icon">${icon('receipt')}</span><div><strong>Labeling revised · PO-025</strong><p>€55 → €60 · corrected supplier invoice</p><p>Admin O · Revision 2 · 23 Oct, 14:32</p></div></div><div class="timeline-item"><span class="timeline-icon">${icon('lock-keyhole')}</span><div><strong>Historical sales preserved</strong><p>12 recorded sales retain their original cost snapshot.</p></div></div></div></section></div>`}
const expenseExamples=[
 {id:'EXP-003',date:'24 Oct',description:'Replacement storage',category:'Storage',allocation:'Pool A-026',amount:120,payer:'Admin O'},
 {id:'EXP-002',date:'22 Oct',description:'Local delivery',category:'Transport',allocation:'Pool B-026',amount:60,payer:'Anna'},
 {id:'EXP-001',date:'20 Oct',description:'Workspace software',category:'Software',allocation:'Business overhead',amount:100,payer:'Admin O'}
];
function expenses(){const entries=expenseExamples.filter(x=>financeInRange('2026-10-'+x.date.slice(0,2))),total=entries.reduce((n,x)=>n+x.amount,0),overhead=entries.filter(x=>x.allocation==='Business overhead').reduce((n,x)=>n+x.amount,0);return pageHead('Extra expenses','',btn('Add expense','plus','data-modal="expense"','primary'))+`<div class="metrics">${metric('Operating expenses',euro(total,2),'receipt','orange','Separate from landed stock cost')}${metric('Allocated to pools',euro(total-overhead,2),'layers','','Linked to investment agreements')}${metric('Business overhead',euro(overhead,2),'building-2','blue','Not charged to individual stock pools')}${metric('Expense entries',String(entries.length),'calendar-days','','')}</div><section class="panel">${panelHead('Expense ledger','Amounts in EUR. Corrections retain the original record.')}${table(['Date','Expense','Category','Allocation','Amount','Paid by',''],entries.map(x=>row([x.date,x.description,x.category,x.allocation,euro(x.amount,2),x.payer,btn('Details','arrow-up-right',`data-expense-detail="${expenseExamples.indexOf(x)}"`,'small')])))}</section>`}
function expenseDetails(index){const x=expenseExamples[index];if(!x)return;openModal('Expense details',keyRows([['Reference',x.id],['Description',x.description],['Category',x.category],['Amount',euro(x.amount,2)],['Allocation',x.allocation],['Paid by',x.payer],['Recorded',x.date+' 2026'],['Revision','1']])+btn('Correct expense','history','data-demo="Expense correction"','mt'))}

