let loginWaterCleanup=null;
function stopLoginWater(){if(loginWaterCleanup){loginWaterCleanup();loginWaterCleanup=null}}
function mountLoginWater(){
 const canvas=document.querySelector('.login-water'),scene=canvas?.parentElement,ctx=canvas?.getContext('2d');if(!ctx)return;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)'),events=new AbortController();
 let w=0,h=0,frame=0,last=0,lastDrop=0,dead=false,waves=[];
 function size(){const rect=scene.getBoundingClientRect();w=rect.width;h=rect.height;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw(performance.now())}
 function point(x,y,t){let dx=0,dy=0;const idle=reduce.matches?0:Math.sin(x*.008+y*.006+t*.00035)*3;
  for(const wave of waves){const age=(t-wave.t)/1000,d=Math.hypot(x-wave.x,y-wave.y),radius=age*150,band=(d-radius)/42,force=Math.sin(band*2.5)*Math.exp(-band*band*.5)*Math.exp(-age*.65)*wave.power;dx+=(x-wave.x)/(d||1)*force;dy+=(y-wave.y)/(d||1)*force}
  return [x+dx+idle,y+dy+idle*.65]
 }
 function draw(t){ctx.clearRect(0,0,w,h);waves=waves.filter(v=>t-v.t<4200);const light=state.theme==='light',step=w<600?38:48;
  const grad=ctx.createLinearGradient(0,0,w,h);grad.addColorStop(0,light?'#765ac54d':'#8c72e45e');grad.addColorStop(.5,light?'#8297d54a':'#597fc059');grad.addColorStop(1,light?'#9c75da52':'#a58ae85e');ctx.strokeStyle=grad;ctx.lineWidth=.7;
  ctx.beginPath();for(let x=-step;x<=w+step;x+=step){for(let y=-step;y<=h+step;y+=12){const p=point(x,y,t);if(y===-step)ctx.moveTo(...p);else ctx.lineTo(...p)}}for(let y=-step;y<=h+step;y+=step){for(let x=-step;x<=w+step;x+=12){const p=point(x,y,t);if(x===-step)ctx.moveTo(...p);else ctx.lineTo(...p)}}ctx.stroke();
 }
 function tick(t){if(dead||document.hidden)return;if(t-last>=32){draw(t);last=t}frame=requestAnimationFrame(tick)}
 function start(){cancelAnimationFrame(frame);if(!dead&&!document.hidden&&!reduce.matches)frame=requestAnimationFrame(tick);else draw(performance.now())}
 function ripple(e){if(reduce.matches||e.target.closest('input,button,a,label'))return;const now=performance.now();if(e.type==='pointermove'&&now-lastDrop<90)return;lastDrop=now;const rect=scene.getBoundingClientRect();waves.push({x:e.clientX-rect.left,y:e.clientY-rect.top,t:now,power:e.type==='pointerdown'?24:14});if(waves.length>8)waves.shift()}
 scene.addEventListener('pointermove',ripple,{passive:true,signal:events.signal});scene.addEventListener('pointerdown',ripple,{passive:true,signal:events.signal});document.addEventListener('visibilitychange',start,{signal:events.signal});reduce.addEventListener('change',start,{signal:events.signal});
 const observer=new ResizeObserver(size);observer.observe(scene);size();start();
 loginWaterCleanup=()=>{dead=true;cancelAnimationFrame(frame);events.abort();observer.disconnect();waves=[]};
}
function login(){return `<div class="login-layout login-scene"><canvas class="login-water" aria-hidden="true"></canvas><section class="login-form-wrap" aria-label="Sign in"><div class="login-form"><h1 class="login-wordmark"><span class="brand-mark" aria-hidden="true">${icon('dna')}</span><span>PeptiStock</span></h1><div class="tabs login-role-tabs" role="group" aria-label="Sign-in role">${[['agent','user-round','Agent'],['admin','shield-check','Administrator']].map(([r,i,l])=>`<button type="button" class="${loginRole===r?'active':''}" data-login-role="${r}" aria-pressed="${loginRole===r}">${icon(i)}${l}</button>`).join('')}</div><form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" type="email" placeholder="you@example.com" autocomplete="off" inputmode="email"></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" placeholder="Enter your password" autocomplete="off"></div><div class="login-options"><label><input type="checkbox"> Remember me</label><button type="button" class="link-btn" data-modal="reset">Forgot password?</button></div><button class="btn primary" type="submit">Log in ${icon('arrow-right')}</button></form></div></section></div>`}
const explanations={
'Cash held':'Business share from collected sales, less confirmed transfers. Pending reported transfers are shown separately; commission stays with the agent.',
'Agent stock & sales':'Blue is unsold stock held by commission agents and partners, valued at current selling prices. Purple is their recorded sales awaiting settlement, including pending transfers and unpaid customer sales. It shows gross sale value, not commission or the net transfer amount. Only confirming a transfer removes its included sales; new sales and physical stock remain. Warehouse stock and prepaid wholesale accounts are excluded. This current balance does not change with the report date filter.',
'Remaining stock value':'Unsold quantity × current selling price. This is potential future revenue, not cash, realized profit or guaranteed income.',
'Stock plus sales':'Remaining stock potential + sales already recorded. Collected payments are part of those sales and are not added again.',
'Sales performance':'Recorded sales are split between the landed cost of sold units and gross profit. Cash collection and capital repayment are tracked separately. The daily chart is illustrative sample data.',
'Distributions':'Agents retain commission and send the business share. Admin confirms receipt against included sales.',
'Sales versus cash':'A recorded sale is revenue. A collection records payment from a customer. A remittance moves collected money from an agent to the business.',
'Landed cost':'Supplier cost converted using the batch exchange rate, plus allocated shipping, labeling, fees and other shared costs. Historical sales retain a cost snapshot.',
'Rounding':'Store money precisely in the backend. Equal thirds use a deterministic remainder rule so every cent is allocated. €1,000 becomes €333.34 + €333.33 + €333.33.',
'Commission':'20% of the actual discounted sale price minus the assigned landed cost. The agreement must define whether extra expenses affect commission and how losses are handled.',
'Stock sample':'The detailed stock table uses the current selling price of each product. Its 54 vials total €5,455. The average is weighted by remaining quantity.'};
let lastFocus=null, loginRole=state.role;
// One fixed dialog shell; preserve page position across nested dialog steps.
let modalPageLock=null;
// Keep the dialog inside the visible viewport, including the mobile keyboard.
let modalTouchPoint=null,modalViewportFrame=0;
function syncModalViewport(){
 if(!modalPageLock)return;
 const root=document.getElementById('modal-root'),v=window.visualViewport;
 if(!root)return;
 const box={top:v?.offsetTop||0,left:v?.offsetLeft||0,width:v?.width||window.innerWidth,height:v?.height||window.innerHeight};
 Object.entries(box).forEach(([k,value])=>root.style[k]=value+'px');
}
function queueModalViewport(){
 if(!modalPageLock||modalViewportFrame)return;
 modalViewportFrame=requestAnimationFrame(()=>{modalViewportFrame=0;syncModalViewport()});
}
function modalScrollAllows(position,client,extent,delta){
 const max=Math.max(0,extent-client);
 return max>1&&((delta>0&&position>1)||(delta<0&&position<max-1));
}
function modalTouchCanScroll(target,dx,dy){
 const horizontal=Math.abs(dx)>Math.abs(dy),axis=horizontal?'X':'Y',delta=horizontal?dx:dy;
 const dialog=target.closest('.modal,.measure-popover');if(!dialog)return false;
 for(let el=target;el&&dialog.contains(el);el=el.parentElement){
  const style=getComputedStyle(el),overflow=style['overflow'+axis];
  if(/auto|scroll/.test(overflow)&&modalScrollAllows(horizontal?el.scrollLeft:el.scrollTop,horizontal?el.clientWidth:el.clientHeight,horizontal?el.scrollWidth:el.scrollHeight,delta))return true;
  if(el===dialog)break;
 }
 return false;
}
document.addEventListener('touchstart',e=>{
 modalTouchPoint=modalPageLock&&e.touches.length===1?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null;
},{passive:true});
document.addEventListener('touchmove',e=>{
 if(!modalPageLock||!modalTouchPoint||e.touches.length!==1)return;
 const t=e.touches[0],dx=t.clientX-modalTouchPoint.x,dy=t.clientY-modalTouchPoint.y;
 modalTouchPoint={x:t.clientX,y:t.clientY};
 if(Math.abs(dx)+Math.abs(dy)<1)return;
 const target=e.target instanceof Element?e.target:e.target.parentElement;
 // Allow a genuine inner scroller; stop sideways panning and rubber-band at its edges.
 if(!target||!modalTouchCanScroll(target,dx,dy)){if(e.cancelable)e.preventDefault()}
},{passive:false});
document.addEventListener('touchend',()=>{modalTouchPoint=null},{passive:true});
document.addEventListener('touchcancel',()=>{modalTouchPoint=null},{passive:true});
window.addEventListener('resize',queueModalViewport);
window.visualViewport?.addEventListener('resize',queueModalViewport);
window.visualViewport?.addEventListener('scroll',queueModalViewport);

function lockModalPage(){
 if(modalPageLock)return;
 closeMobileNavigation();
 const body=document.body,keys=['position','top','left','width','overflow','paddingRight'];
 modalPageLock={x:window.scrollX,y:window.scrollY,styles:Object.fromEntries(keys.map(k=>[k,body.style[k]])),inert:[]};
 const gutter=Math.max(0,window.innerWidth-document.documentElement.clientWidth);
 if(gutter)body.style.paddingRight=`${parseFloat(getComputedStyle(body).paddingRight)+gutter}px`;
 body.style.position='fixed';body.style.top=`-${modalPageLock.y}px`;body.style.left=`-${modalPageLock.x}px`;body.style.width='100%';body.style.overflow='hidden';
 document.documentElement.classList.add('dialog-open');
 syncModalViewport();
 ['app','preview-toolbar'].forEach(id=>{const el=document.getElementById(id);if(el){modalPageLock.inert.push([el,el.inert]);el.inert=true}});
}
function unlockModalPage(){
 if(!modalPageLock)return;
 const saved=modalPageLock;modalPageLock=null;
 modalTouchPoint=null;cancelAnimationFrame(modalViewportFrame);modalViewportFrame=0;
 const root=document.getElementById('modal-root');if(root)root.removeAttribute('style');
 Object.entries(saved.styles).forEach(([k,v])=>document.body.style[k]=v);
 saved.inert.forEach(([el,value])=>el.inert=value);
 document.documentElement.classList.remove('dialog-open');
 window.scrollTo({left:saved.x,top:saved.y,behavior:'instant'});
}
function openModal(title,body,wide=false){
 dismissMeasureHelp();motionClearExits();protocolCloseViewer();
 if(!modalPageLock){lastFocus=document.activeElement;lockModalPage()}
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><h2 id="modal-title">${title}${/data-(?:info|help)/.test(title)?'':measureInfo(title)}</h2><button class="icon-btn" data-close aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div></section></div>`;
 icons();$('.modal [data-close]').focus({preventScroll:true});
}
function closeModal(){
 if(!$('.modal'))return;
 dismissMeasureHelp();protocolCloseViewer();motionDismiss($('#modal-root > .modal-overlay'));$('#modal-root').innerHTML='';unlockModalPage();
 const target=lastFocus?.isConnected&&!lastFocus.closest('[inert]')?lastFocus:$$('.topbar button').find(el=>el.getClientRects().length&&!el.disabled);target?.focus({preventScroll:true});
 lastFocus=null;
}
