 const error=$('#product-editor-error');const threshold=Number($('#f-low-stock-threshold').value);if(!$('#f-low-stock-threshold').value||!Number.isInteger(threshold)||threshold<0||threshold>100000){error.textContent='Low-stock threshold must be a whole number from 0 to 100,000.';return}if(!name||!dose||!priceInput.value||!priceInput.checkValidity()||!Number.isFinite(price)||price<0||!productCategories.some(c=>c.id===category)||[...document.querySelectorAll('.modal input[type=number]')].some(e=>!e.checkValidity())){error.textContent='Enter a name, strength, selling price and category.';return}
