document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form')toast('Sign-in is not connected in this design. Use the Admin or Agent switch to preview.')});
document.addEventListener('keydown',e=>{
 const help=document.getElementById('measure-help'),dialog=$('.modal'),drawer=mobileNavigationScroll!==undefined;
 if(e.key==='Escape'){
  if(help){const trigger=activeHelpTrigger;dismissMeasureHelp();trigger?.focus({preventScroll:true})}
  else if(dialog)closeModal();
  else if(drawer)closeMobileNavigation();
  else return;
  e.preventDefault();e.stopImmediatePropagation();return;
 }
 const scope=help||dialog;
 if(e.key==='Tab'&&scope){
  const items=[...scope.querySelectorAll('button,input,select,textarea,summary,a[href],[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0&&!el.closest('[hidden],[inert]')&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
  if(!items.length){e.preventDefault();scope.focus({preventScroll:true});return}
  const first=items[0],last=items.at(-1),active=document.activeElement;
  if(!scope.contains(active)||(e.shiftKey&&active===first)){e.preventDefault();(e.shiftKey?last:first).focus({preventScroll:true})}
  else if(!e.shiftKey&&active===last){e.preventDefault();first.focus({preventScroll:true})}
 }
},true);
window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==state.page){closeModal();state.page=location.hash.slice(1)||'dashboard';render()}});render();


// Reflow existing table records on phones; never clone editable controls or ledger rows.
function prepareMobileRecords(w,table){
 if(w.closest('.agent-stock-panel,.orders-desktop-list,.agent-overview-desktop,.transfer-lines'))return;
 w.classList.add('mobile-records');
 const heads=[...table.querySelectorAll('thead th')];
 const labels=heads.map(h=>{const c=h.cloneNode(true);c.querySelectorAll('button').forEach(b=>b.remove());return c.textContent.trim()});
 if(labels.includes('To business')&&labels.includes('Agent'))table.classList.add('mobile-sales-records');
 if(labels.includes('Default selling price'))table.classList.add('mobile-catalogue-records');
 const editable=!!table.querySelector('tbody input,tbody select,tbody textarea');
 table.querySelectorAll('tbody > tr').forEach((r,ri)=>{
  if(r.dataset.mobileRecord)return;
  r.dataset.mobileRecord='true';
  const cells=[...r.children];
  if(cells.length===1&&cells[0].colSpan>1){r.classList.add('record-empty');return}
  let secondary=0;
  cells.forEach((c,i)=>{
   const label=labels[i]||'';c.dataset.column=label;c.dataset.label=label;
   if(i===0){c.classList.add('record-identity');return}
   if(!label||/^action$/i.test(label)){c.classList.add('record-actions');c.dataset.label='';return}
   if(/^(status|settlement|payment)$/i.test(label)){c.classList.add('record-status');return}
   if(/^(product|products|movement|event|change|basis|allocation)$/i.test(label))c.classList.add('record-wide');
   if(!editable&&cells.length>5&&/^(commission|to business|paid|received|damaged|landed \/ vial|allocation|paid by)$/i.test(label)){c.classList.add('record-extra');secondary++}
  });
  if(secondary){
   const cell=document.createElement('td');cell.className='record-disclosure';
   const button=document.createElement('button');button.type='button';button.className='record-details-toggle';button.setAttribute('aria-expanded','false');
   const name=cells[0].textContent.trim().split('\n')[0];button.setAttribute('aria-label','More details for '+name);button.textContent='More details';
   button.addEventListener('click',()=>{const expanded=r.classList.toggle('record-expanded');button.setAttribute('aria-expanded',String(expanded));button.textContent=expanded?'Less details':'More details'});
   cell.append(button);r.append(cell);
  }
 });
}

// Shared table affordances also cover tables inserted into dialogs or re-rendered views.
(()=>{
 const tables=new Map();let scheduled=false,serial=0;
 const schedule=()=>{if(!scheduled){scheduled=true;requestAnimationFrame(refresh)}};
 const resize=new ResizeObserver(schedule);
 function update(w,entry){
  const max=w.scrollWidth-w.clientWidth,overflow=max>2;
  entry.cue.hidden=!overflow;
  w.classList.toggle('has-horizontal-overflow',overflow);
  if(overflow){
   w.tabIndex=0;w.setAttribute('role','region');w.setAttribute('aria-label','Scrollable table');
   const start=w.scrollLeft<2,end=w.scrollLeft>=max-2;
   entry.left.disabled=start;entry.right.disabled=end;
   const label=end?'End of table':matchMedia('(max-width:760px)').matches?'Swipe for more columns':'Scroll for more columns';
   if(entry.label.textContent!==label)entry.label.textContent=label;
   entry.cue.style.setProperty('--table-position',`${Math.min(100,Math.max(0,w.scrollLeft/max*100))}%`);
  }else{w.removeAttribute('tabindex');w.removeAttribute('role');w.removeAttribute('aria-label')}
 }
 function refresh(){
  scheduled=false;
  for(const [w,entry] of tables){if(!w.isConnected){resize.unobserve(w);resize.unobserve(entry.table);entry.cue.remove();tables.delete(w)}}
  document.querySelectorAll('.table-wrap').forEach(w=>{
   const table=w.querySelector('table');if(!table)return;
   let entry=tables.get(w);
   if(!entry){
    const cue=document.createElement('div');cue.className='table-scroll-cue';cue.hidden=true;
    const id=w.id||(w.id=`scroll-table-${++serial}`);
    cue.innerHTML=`<span class="table-scroll-label"></span><div class="table-scroll-track" aria-hidden="true"><i></i></div><button type="button" aria-label="Scroll table left" aria-controls="${id}">‹</button><button type="button" aria-label="Scroll table right" aria-controls="${id}">›</button>`;
    w.before(cue);const [left,right]=cue.querySelectorAll('button');
    entry={cue,left,right,label:cue.querySelector('span'),table};tables.set(w,entry);
    for(const [button,direction] of [[left,-1],[right,1]])button.addEventListener('click',()=>w.scrollBy({left:direction*w.clientWidth*.75,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}));
    w.addEventListener('scroll',()=>update(w,entry),{passive:true});resize.observe(w);resize.observe(table);
    [...table.querySelectorAll('thead th')].forEach((th,i)=>{
     if(/^(product|products|peptide)$/i.test(th.textContent.trim()))table.querySelectorAll('tr').forEach(row=>row.children[i]?.classList.add('table-product-cell'));
    });
   }
   prepareMobileRecords(w,table);
   update(w,entry);
  });
 }
 new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});
 window.addEventListener('resize',schedule);schedule();
})();

// Category selections affect presentation only; this remains an in-memory design preview.
document.addEventListener('change',e=>{if(e.target.id==='catalogue-category'){catalogueCategory=e.target.value;applyStockFilter()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-save-product-preview]'))saveProductPreview();if(e.target.closest('[data-category-help]')){const help=$('#category-help');motionSetVisible(help,!(uiMotion.visibility.get(help)?.visible??!help.hidden))}});

// Mobile drawer owns scrolling while open; preserve the underlying page position.
var mobileNavigationScroll;
function closeMobileNavigation(){
 if(mobileNavigationScroll===undefined)return;
 const y=mobileNavigationScroll;mobileNavigationScroll=undefined;
 document.documentElement.classList.remove('navigation-open');
 document.body.style.removeProperty('position');document.body.style.removeProperty('top');document.body.style.removeProperty('width');
 $('.sidebar')?.classList.remove('open');motionSyncControls();
 $$('.main,.mobile-nav,#preview-toolbar').forEach(el=>el.inert=false);
 const trigger=$('[aria-controls="workspace-navigation"].mobile-menu');trigger?.setAttribute('aria-expanded','false');
 window.scrollTo({top:y,behavior:'instant'});trigger?.focus({preventScroll:true});
}
function toggleMobileNavigation(){
 if(mobileNavigationScroll!==undefined){closeMobileNavigation();return}
 if(!window.matchMedia('(max-width:700px)').matches)return;
 mobileNavigationScroll=window.scrollY;
 document.body.style.position='fixed';document.body.style.top=`-${mobileNavigationScroll}px`;document.body.style.width='100%';
 document.documentElement.classList.add('navigation-open');$('.sidebar')?.classList.add('open');motionSyncControls();
 $('[aria-controls="workspace-navigation"].mobile-menu')?.setAttribute('aria-expanded','true');
 $$('.main,.mobile-nav,#preview-toolbar').forEach(el=>el.inert=true);
 $('.sidebar nav button')?.focus({preventScroll:true});
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileNavigationScroll!==undefined){e.preventDefault();closeMobileNavigation()}});
window.addEventListener('resize',()=>{if(window.innerWidth>700)closeMobileNavigation()});

// Shared explanations dismiss on a second tap, outside tap, Escape or navigation.
document.addEventListener('click',e=>{const b=e.target.closest('[data-help]');if(b){showMeasureHelp(b,b.dataset.help);return}if(e.target.closest('[data-help-close]')){const trigger=activeHelpTrigger;dismissMeasureHelp();trigger?.focus({preventScroll:true});return}if(!e.target.closest('#measure-help'))dismissMeasureHelp();if(e.target.classList.contains('modal-overlay'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')dismissMeasureHelp()});
window.addEventListener('resize',dismissMeasureHelp);
window.addEventListener('scroll',()=>{if(activeHelpTrigger)dismissMeasureHelp()},{passive:true});

measureExplanations['Matched comparison']='Compares the same elapsed part of the previous period. For example, Monday to Wednesday this week is compared with Monday to Wednesday last week. Today stops at the same time of day in both periods.';
document.addEventListener('click',e=>{const b=e.target.closest('[data-info]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();showMeasureHelp(b,b.dataset.info)},true);
